Object.assign(tr.ta,{'createSocietyTitle':'உங்கள் Society360 சங்கத்தை உருவாக்கவும்','createSocietyText':'சங்கம், முதல் Society Admin கணக்கு மற்றும் சந்தாவை ஒன்றாக உருவாக்கவும். உங்கள் கட்டண முறை இணைக்கப்படும் வரை கட்டணம் நிலுவையில் இருக்கும்.','chooseSubscription':'சந்தாவைத் தேர்ந்தெடுக்கவும்','plansAnnualNote':'திட்டங்கள் ஆண்டு அடிப்படையிலானவை. நிலுவை கட்டண நிலையுடன் சந்தா உடனடியாக உருவாக்கப்படும். தற்போது எந்த கட்டண நுழைவாயிலும் அழைக்கப்படாது.','createSocietyAndAdmin':'சங்கம் மற்றும் நிர்வாகி கணக்கை உருவாக்கவும்','creatingSociety':'சங்கம் உருவாக்கப்படுகிறது…','societyCreatedRedirect':'சங்கம் உருவாக்கப்பட்டது. உங்கள் Society Admin பணியிடத்திற்குச் செலுத்தப்படுகிறது…','societyCreationFailed':'சங்கத்தை உருவாக்க முடியவில்லை.','serverTryAgain':'சேவையகத்தை அணுக முடியவில்லை. மீண்டும் முயற்சிக்கவும்.','plansUnavailable':'திட்டங்கள் கிடைக்கவில்லை','tryAfterDatabase':'தரவுத்தள அமைப்புக்குப் பிறகு மீண்டும் முயற்சிக்கவும்.','societyName':'சங்கத்தின் பெயர்','administratorName':'நிர்வாகியின் பெயர்','adminLoginName':'நிர்வாகி உள்நுழைவு பெயர்','minimumPassword':'குறைந்தது 10 எழுத்துகள்','email':'மின்னஞ்சல்','phone':'தொலைபேசி','societyAddress':'சங்க முகவரி','fullName':'முழுப் பெயர்','multiSociety':'பல சங்கங்கள்','dynamicRights':'மாறும் உரிமைகள்','billingChip':'பில்லிங்','sixLanguages':'6 மொழிகள்','secureAccess':'Society360 · பாதுகாப்பான அணுகல்'});
const fieldAliases={'full_name':'Consumer Name','customer_code':'Customer Code','phone':'Phone','email':'Email','flat_no':'Flat Number','wing':'Wing','building':'Building','area_sqft':'Area Sq.Ft.','outstanding':'Outstanding','total_billed':'Total Bill Amount','total_paid':'Paid Amount','parking_count':'Parking','vehicle_count':'Vehicles','bill_no':'Bill No','bill_month':'Month','total_amount':'Total Bill Amount','paid_amount':'Paid Amount','balance':'Balance','due_date':'Due Date','status':'Status','payment_no':'Payment No','payment_date':'Payment Date','payment_mode':'Payment Mode','reference_no':'Reference No','complaint_no':'Complaint No','category':'Category','title':'Title','priority':'Priority','created_at':'Created','visitor_name':'Visitor','visitor_type':'Type','purpose':'Purpose','entry_time':'Entry','exit_time':'Exit','slot_no':'Slot','slot_type':'Type','charge':'Charge','assigned_flat':'Flat','account_type_name':'Account Type','last_login_at':'Last Login','login_count':'Login Count','failed_login_count':'Failed Count','last_failed_at':'Last Failed'};
let current=allowed(localStorage.getItem('society360-language')||'en');
const sourceTextNodes=new WeakMap();
function translateText(key){if(key==null)return '';const s=String(key);const base=fieldAliases[s]||s;const dict=tr[current]||{};if(dict[base]!==undefined)return dict[base];if(en[base]!==undefined&&current==='en')return en[base];if(s.startsWith('Hello, '))return (dict['Hello']||'Hello')+', '+s.slice(7);if(s.startsWith('Edit Role: '))return (dict['Edit Role: ']||'Edit Role: ')+s.slice(11);if(s.startsWith('Payment accepted. Transaction ID '))return (dict['Payment accepted. Transaction ID ']||'Payment accepted. Transaction ID ')+s.slice(36);if(s.startsWith('Record payment of ₹'))return (dict['Record payment of ₹']||'Record payment of ₹')+s.slice(19);return en[base]||base;}
function shouldSkip(el){return !el||['SCRIPT','STYLE','NOSCRIPT','OPTION','TEXTAREA'].includes(el.tagName)||el.closest('[data-i18n-ignore]');}
function translateNodeTree(root){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];let n;while((n=walker.nextNode())){const p=n.parentElement;if(shouldSkip(p))continue;const raw=n.nodeValue||'';const s=raw.trim();if(!s)continue;const source=sourceTextNodes.get(n)||s;if(!sourceTextNodes.has(n))sourceTextNodes.set(n,source);const translated=translateText(source);if(translated!==source)nodes.push([n,raw,s,translated]);}nodes.forEach(([node,raw,s,t])=>node.nodeValue=raw.replace(s,t));}
function translateAttributes(root){(root||document).querySelectorAll?.('[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-ca-i18n],[data-ca-placeholder]').forEach(el=>{const key=el.getAttribute('data-i18n')||el.getAttribute('data-ca-i18n');if(key)el.textContent=translateText(key);const p=el.getAttribute('data-i18n-placeholder')||el.getAttribute('data-ca-placeholder');if(p){if(!el.hasAttribute('data-s360-source-placeholder'))el.setAttribute('data-s360-source-placeholder',p);el.setAttribute('placeholder',translateText(el.getAttribute('data-s360-source-placeholder')));}const title=el.getAttribute('data-i18n-title');if(title){if(!el.hasAttribute('data-s360-source-title'))el.setAttribute('data-s360-source-title',title);el.setAttribute('title',translateText(el.getAttribute('data-s360-source-title')));}});}
function cleanGarbage(root){const walker=document.createTreeWalker(root||document.body,NodeFilter.SHOW_TEXT);const nodes=[];let n;while((n=walker.nextNode())){if(shouldSkip(n.parentElement))continue;const s=n.nodeValue||'';if(s.includes('\\n')||s.includes('�'))nodes.push(n);}nodes.forEach(n=>n.nodeValue=(n.nodeValue||'').split('\\n').join(' ').split('�').join(''));}
function apply(){document.documentElement.lang=languages[current].locale.split('-')[0];document.querySelectorAll('select#language-select,[data-language-selector]').forEach(sel=>{const val=current;sel.innerHTML='';Object.entries(languages).forEach(([code,info])=>{const o=document.createElement('option');o.value=code;o.textContent=info.name;sel.appendChild(o);});sel.value=val;});translateAttributes(document);translateNodeTree(document.body);cleanGarbage(document.body);}
let observer=null;
function init(){current=allowed(localStorage.getItem('society360-language')||current);if(!observer&&document.body){observer=new MutationObserver(ms=>{for(const m of ms){m.addedNodes.forEach(x=>{if(x.nodeType===1){translateAttributes(x);translateNodeTree(x);cleanGarbage(x)}})}});observer.observe(document.body,{childList:true,subtree:true});}apply();}
function setLanguage(code){current=allowed(code);localStorage.setItem('society360-language',current);apply();window.dispatchEvent(new CustomEvent('society360-language-changed',{detail:{language:current}}));}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>init(),{once:true});else init();
function ensureToastStyles(){if(document.getElementById('s360-toast-style'))return;const s=document.createElement('style');s.id='s360-toast-style';s.textContent='.s360-toast-wrap{position:fixed;right:18px;bottom:18px;z-index:99999;display:flex;flex-direction:column;gap:10px;pointer-events:none}.s360-toast{min-width:260px;max-width:min(420px,calc(100vw - 36px));padding:12px 14px;border:1px solid #e5e7eb;border-radius:12px;background:#fff;box-shadow:0 14px 40px rgba(15,23,42,.16);font:600 12px Arial,sans-serif;color:#1f2937;opacity:0;transform:translateY(10px);transition:.2s}.s360-toast.show{opacity:1;transform:translateY(0)}.s360-toast.success{border-left:4px solid #16a34a}.s360-toast.error{border-left:4px solid #dc2626}.s360-toast.warning{border-left:4px solid #d97706}.s360-toast.info{border-left:4px solid #2563eb}@media(max-width:600px){.s360-toast-wrap{left:12px;right:12px;bottom:12px}.s360-toast{min-width:0;width:100%}}';document.head.appendChild(s)}
function toast(message,type='info',duration=3200){ensureToastStyles();let wrap=document.querySelector('.s360-toast-wrap');if(!wrap){wrap=document.createElement('div');wrap.className='s360-toast-wrap';wrap.setAttribute('aria-live','polite');document.body.appendChild(wrap)}const el=document.createElement('div');el.className='s360-toast '+type;el.textContent=translateText(message);wrap.appendChild(el);requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),220)},duration)}
window.Society360Toast={show:toast,success:m=>toast(m,'success'),error:m=>toast(m,'error'),warning:m=>toast(m,'warning'),info:m=>toast(m,'info')};
if(!window.__society360AlertPatched){window.__society360AlertPatched=true;window.alert=function(message){toast(message,String(message||'').toLowerCase().includes('success')?'success':'error')}}
window.Society360I18n={
 init,apply,setLanguage,translateText,currentLanguage:()=>current,locale:()=>languages[current].locale,t:translateText,
 languages:Object.freeze(languages)
};
